import 'package:flame_audio/flame_audio.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Sound effects and music. All sounds in assets/audio were generated by
/// tool/make_sounds.py for this project, so there are no licensing worries.
/// Swap the files (same names) to change the sound; every call fails quietly.
class GameAudio {
  bool enabled = true;
  AudioPlayer? _music;
  double _tempo = 1;
  bool _loaded = false;

  static const tap = 'tap.wav';
  static const success = 'success.wav';
  static const fail = 'fail.wav';
  static const reveal = 'reveal.wav';
  static const music = 'loop.wav';

  Future<void> preload() async {
    if (_loaded) return;
    try {
      await FlameAudio.audioCache.loadAll([tap, success, fail, reveal, music]);
      _loaded = true;
    } catch (e) {
      debugPrint('Audio preload failed: $e');
    }
  }

  Future<void> _play(String file, {double volume = 0.8}) async {
    if (!enabled) return;
    try {
      await FlameAudio.play(file, volume: volume);
    } catch (e) {
      debugPrint('Audio play failed: $e');
    }
  }

  void playTap() => _play(tap, volume: 0.5);
  void playSuccess() => _play(success, volume: 0.6);
  void playFail() => _play(fail);
  void playReveal() => _play(reveal);

  Future<void> startMusic() async {
    if (!enabled || _music != null) return;
    try {
      _music = await FlameAudio.loop(music, volume: 0.35);
      await _music?.setPlaybackRate(_tempo);
    } catch (e) {
      debugPrint('Music failed: $e');
    }
  }

  /// Music speeds up as the run goes on.
  Future<void> setTempo(double tempo) async {
    _tempo = tempo;
    try {
      await _music?.setPlaybackRate(tempo);
    } catch (_) {}
  }

  Future<void> stopMusic() async {
    final m = _music;
    _music = null;
    try {
      await m?.stop();
      await m?.dispose();
    } catch (_) {}
  }
}

/// Phone vibrations. Does nothing on the web or when switched off.
class GameHaptics {
  bool enabled = true;

  void tap() {
    if (enabled) HapticFeedback.selectionClick();
  }

  void success() {
    if (enabled) HapticFeedback.lightImpact();
  }

  void fail() {
    if (enabled) HapticFeedback.heavyImpact();
  }

  void chaos() {
    if (enabled) HapticFeedback.mediumImpact();
  }
}
